class InboundInvoice {
  constructor(
    id,
    draft_id,
    source_entity,
    source_entity_name,
    invoice_number,

  ) {
    this.id = id;
    this.draft_id = draft_id;
    this.source_entity = source_entity;
    this.source_entity_name = source_entity_name;
    this.invoice_number = invoice_number;

  }
}

export default InboundInvoice;
